from collections import deque

class Solution:
    def window(self, times: list[float], duration: float, limit: int) -> list[bool]:
        accepted=deque()
        result=[]
        for now in times:
            while accepted and accepted[0]<=now-duration:accepted.popleft()
            ok=len(accepted)<limit
            if ok:accepted.append(now)
            result.append(ok)
        return result

